(* [comment removed for export] *)
Ltac call_svat p n i rest P sp :=
  lazymatch goal with
  | SD : verb_side ?m0 ?lo ?shi _ _, CEIL : aceil <= ?lo, FR : rw_cells _ ?mc (bv_unsigned sp + -40) _, ST : stk _ ?mc ?lo _,
    MI : mem_inv _ ?mc, MU : munch _ ?m0 ?mc, WM : wmono _ ?m0 ?mc, SPAL : hideL (_ mod 16 = 0) |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let ACc := fresh "ACc" in let SKc := fresh "SKc" in let ASV := fresh "ASV" in let S := fresh "SA" in
    destruct (verb_side_now _ mc _ _ _ _ _ SD MU WM CEIL) as (ACc & SKc & _ & _);
    assert (ASV : accessible mc (bv_unsigned sp + -40) 16) by (eapply stack0_accessible; [exact SKc | lia | lia | lia]);
    clear SKc;
    pose proof svat_spec as S; unfold svat_stmt, svat_post, ASV_LEAF_STACK, P_A_SV_INDEX, wz in S;
    callZc (S (bv_unsigned sp + -40) p n i rest lo) (clear S FR ST ACc ASV);
    [ exact FR | lia | lia | lia | rewrite ?unsigned_lit by lia; exact ST
    | rewrite ?unsigned_lit by lia; lia | rewrite ?unsigned_lit by lia; cbn [cells_size csize Nat.add length]; lia | exact MI
    | exact CEIL | exact ACc | exact ASV | unfold hideL in SPAL; clear - SPAL; Z.div_mod_to_equations; lia
    | lia | ];
    verb_names sp lo;
    verb_rebuild_ctx m0 sp P
  end.

(* [comment removed for export] *)
Ltac call_svrp p n k rest P sp :=
  lazymatch goal with
  | SD : verb_side ?m0 ?lo ?shi _ _, CEIL : aceil <= ?lo, FR : rw_cells _ ?mc (bv_unsigned sp + -40) _, ST : stk _ ?mc ?lo _,
    MI : mem_inv _ ?mc, MU : munch _ ?m0 ?mc, WM : wmono _ ?m0 ?mc, SPAL : hideL (_ mod 16 = 0) |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let ACc := fresh "ACc" in let SKc := fresh "SKc" in let ASV := fresh "ASV" in let S := fresh "SR" in
    destruct (verb_side_now _ mc _ _ _ _ _ SD MU WM CEIL) as (ACc & SKc & _ & _);
    assert (ASV : accessible mc (bv_unsigned sp + -40) 16) by (eapply stack0_accessible; [exact SKc | lia | lia | lia]);
    clear SKc;
    pose proof svrp_spec as S; unfold svrp_stmt, svrp_post, ASV_LEAF_STACK, P_A_SV_REMOVE_PREFIX, wz in S;
    callZc (S (bv_unsigned sp + -40) p n k rest lo) (clear S FR ST ACc ASV);
    [ exact FR | lia | lia | lia | rewrite ?unsigned_lit by lia; exact ST
    | rewrite ?unsigned_lit by lia; lia | rewrite ?unsigned_lit by lia; cbn [cells_size csize Nat.add length]; lia | exact MI
    | exact CEIL | exact ACc | exact ASV | unfold hideL in SPAL; clear - SPAL; Z.div_mod_to_equations; lia
    | apply awin_stack; lia | lia | ];
    repeat match goal with H : accessible _ (bv_unsigned sp + -40) _ |- _ => clear H end;
    verb_names sp lo;
    verb_rebuild_ctx m0 sp P
  end.

